      "id": 1,
      "claim": "In a DFS of a connected undirected graph, any edge not in the DFS tree is a back edge that connects a vertex to one of its ancestors in the DFS tree.",
      "evidence": "When DFS explores an edge (x,y), if y has already been visited then y lies on the current recursion stack (the path from the root to x); otherwise the edge would be taken as a tree edge. Undirected graphs have no cross or forward edges.",
      "weight": 0.3,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "For a non‑tree edge (u,v) with pre(u) < pre(v), u is an ancestor of v in the DFS tree.",
      "evidence": "By step 1 the edge is a back edge, i.e., it joins an ancestor–descendant pair. The vertex discovered earlier (smaller preorder number) is the ancestor.",
      "weight": 0.4,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "If u is an ancestor of v, then the lowest common ancestor of u and v is u.",
      "evidence": "Definition of lowest common ancestor: the deepest vertex that is ancestor of both. When one vertex is ancestor of the other, that ancestor is the deepest common ancestor.",
      "weight": 0.2,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "In a postorder traversal, a descendant finishes before its ancestor; therefore for ancestor u and descendant v we have post(v) < post(u).",
      "evidence": "Postorder records a vertex after all vertices in its subtree have been recorded.",
      "weight": 0.3,
      "depends_on": [2]
    }
  ],
  "answer": "D",
  "confidence": 0.97,
